// Table lookup + linear interpolation, floor
static inline int64_t lut(const int64_t *t, int16_t q)
{
    int32_t u = (int32_t)q + 32768, k = u >> TS, fr = u & ((1 << TS) - 1);
    return t[k] + (((t[k + 1] - t[k]) * fr) >> TS);
}

